SELECT "users"."id", "users"."email", "users"."name", "users"."nickname", "users"."age", "users"."status", "users"."prev_status", "users"."balance", "users"."score", "users"."is_admin", "users"."tags", "users"."meta", "users"."settings", "users"."external_id", "users"."manager_id", "users"."birthday", "users"."created_at" FROM "users" WHERE "users"."name" > $1 OR "users"."name" = $2 AND "users"."id" < $3 ORDER BY "users"."name" ASC, "users"."id" DESC
